1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Tests\Acceptance\Legacy;
6	
7	use App\Identity\Infrastructure\Security\DemoCustomerProvider;
8	use App\Inventory\Domain\Repository\StockItemRepository;
9	use App\Ordering\Domain\Model\Order;
10	use App\Ordering\Domain\Repository\OrderRepository;
11	use App\Ordering\Domain\ValueObject\CustomerId;
12	use App\Ordering\Domain\ValueObject\OrderId;
13	use App\Ordering\Domain\ValueObject\OrderStatus;
14	use App\Ordering\Domain\ValueObject\ProductId;
15	use App\SharedKernel\Domain\Currency;
16	use App\SharedKernel\Domain\Money;
17	use App\Tests\Support\Catalog;
18	use App\Tests\Support\TestDatabase;
19	use Doctrine\DBAL\Connection;
20	use Doctrine\ORM\EntityManagerInterface;
21	use PHPUnit\Framework\Attributes\Test;
22	use Symfony\Bundle\FrameworkBundle\KernelBrowser;
23	use Symfony\Bundle\FrameworkBundle\Test\WebTestCase;
24	
25	/**
26	 * Storno ze staré administrace: zaplacená částka se zaznamená k vrácení
27	 * (peníze vrací obchod ručně) a zboží se vrátí na sklad.
28	 */
29	final class CancelOrderTest extends WebTestCase
30	{
31	    private KernelBrowser $client;
32	
33	    protected function setUp(): void
34	    {
35	        TestDatabase::reset();
36	        // stará administrace drží spojení v globální proměnné
37	        $GLOBALS['db'] = null;
38	        $this->client = self::createClient();
39	        $this->client->disableReboot();
40	        Catalog::seed(self::getContainer()->get(Connection::class));
41	    }
42	
43	    #[Test]
44	    public function paidOrderIsCancelledFromOrderDetail(): void
45	    {
46	        $this->loginAs('obchod@example.com');
47	        // klávesnice 2 × 300 Kč, sleva 100 Kč: zaplaceno 500 Kč
48	        $order = $this->order(pay: true);
49	
50	        $this->client->request('GET', '/admin/legacy/order?id='.$order->id->value);
51	        $this->client->submitForm('Stornovat objednávku', ['reason' => 'Zákazník si to rozmyslel']);
52	
53	        self::assertSelectorTextContains('.flash', 'Objednávka stornována');
54	        self::assertSelectorTextContains('.refund', '500');
55	        self::assertSelectorNotExists('input[value="Stornovat objednávku"]');
56	        self::getContainer()->get(EntityManagerInterface::class)->clear();
57	        $cancelled = self::getContainer()->get(OrderRepository::class)->get($order->id);
58	        self::assertSame(OrderStatus::Cancelled, $cancelled->status);
59	        self::assertSame('Zákazník si to rozmyslel', $cancelled->cancellationNote);
60	        self::assertEquals(new Money(500_00, Currency::CZK), $cancelled->refundAmount());
61	        self::assertSame(10, $this->keyboardsAvailable());
62	    }
63	
64	    #[Test]
65	    public function unpaidOrderIsCancelledWithoutRefund(): void
66	    {
67	        $this->loginAs('obchod@example.com');
68	        $order = $this->order(pay: false);
69	
70	        $this->client->request('GET', '/admin/legacy/order?id='.$order->id->value);
71	        $this->client->submitForm('Stornovat objednávku');
72	
73	        self::assertSelectorTextContains('.flash', 'Objednávka stornována');
74	        self::assertSelectorNotExists('.refund');
75	        self::getContainer()->get(EntityManagerInterface::class)->clear();
76	        $cancelled = self::getContainer()->get(OrderRepository::class)->get($order->id);
77	        self::assertSame(OrderStatus::Cancelled, $cancelled->status);
78	        self::assertNull($cancelled->refundAmount());
79	        self::assertSame(10, $this->keyboardsAvailable());
80	    }
81	
82	    #[Test]
83	    public function shippedOrderStaysShipped(): void
84	    {
85	        $this->loginAs('obchod@example.com');
86	        $order = $this->order(pay: true);
87	        $order->ship();
88	        self::getContainer()->get(OrderRepository::class)->save($order);
89	
90	        $this->client->request('GET', '/admin/legacy/order?id='.$order->id->value);
91	        self::assertSelectorNotExists('input[value="Stornovat objednávku"]');
92	        $this->client->request('POST', '/admin/legacy/order_cancel?id='.$order->id->value, ['_csrf' => $this->csrfToken()]);
93	
94	        self::assertSelectorTextContains('.flash.error', 'stornovat nejde');
95	        self::getContainer()->get(EntityManagerInterface::class)->clear();
96	        $unchanged = self::getContainer()->get(OrderRepository::class)->get($order->id);
97	        self::assertSame(OrderStatus::Shipped, $unchanged->status);
98	        self::assertNull($unchanged->refundAmount());
99	    }
100	
101	    #[Test]
102	    public function cancelWithoutCsrfTokenIsRejected(): void
103	    {
104	        $this->loginAs('obchod@example.com');
105	        $order = $this->order(pay: true);
106	
107	        $this->client->request('POST', '/admin/legacy/order_cancel?id='.$order->id->value);
108	
109	        self::assertResponseStatusCodeSame(403);
110	        self::getContainer()->get(EntityManagerInterface::class)->clear();
111	        self::assertSame(OrderStatus::Paid, self::getContainer()->get(OrderRepository::class)->get($order->id)->status);
112	    }
113	
114	    #[Test]
115	    public function warehouseStaffCannotCancel(): void
116	    {
117	        $this->loginAs('sklad@example.com');
118	        $order = $this->order(pay: true);
119	
120	        $this->client->request('POST', '/admin/legacy/order_cancel?id='.$order->id->value, ['_csrf' => $this->csrfToken()]);
121	
122	        self::assertResponseStatusCodeSame(403);
123	        self::getContainer()->get(EntityManagerInterface::class)->clear();
124	        self::assertSame(OrderStatus::Paid, self::getContainer()->get(OrderRepository::class)->get($order->id)->status);
125	    }
126	
127	    private function loginAs(string $email): void
128	    {
129	        $this->client->loginUser(
130	            self::getContainer()->get(DemoCustomerProvider::class)->loadUserByIdentifier($email),
131	        );
132	    }
133	
134	    private function order(bool $pay): Order
135	    {
136	        $order = Order::place(OrderId::generate(), CustomerId::generate());
137	        $order->addItem(ProductId::fromString(Catalog::KEYBOARD), 2, new Money(300_00, Currency::CZK));
138	        $order->applyDiscount(new Money(100_00, Currency::CZK));
139	        $order->confirm();
140	        if ($pay) {
141	            $order->markPaid();
142	        }
143	        self::getContainer()->get(OrderRepository::class)->save($order);
144	        self::assertSame(8, $this->keyboardsAvailable());
145	
146	        return $order;
147	    }
148	
149	    private function csrfToken(): ?string
150	    {
151	        return $this->client->request('GET', '/admin/legacy/orders')->filter('input[name="_csrf"]')->first()->attr('value');
152	    }
153	
154	    private function keyboardsAvailable(): int
155	    {
156	        return self::getContainer()->get(StockItemRepository::class)->get(ProductId::fromString(Catalog::KEYBOARD))->available();
157	    }
158	}
159

auth_require();

$stav = isset($_GET['stav']) ? (string) $_GET['stav'] : '';
$od = isset($_GET['od']) ? (string) $_GET['od'] : date('Y-m-d', strtotime('-7 days'));
$razeni = isset($_GET['razeni']) ? (string) $_GET['razeni'] : 'placed_at DESC';

$sql = "SELECT * FROM orders WHERE placed_at >= '" . $od . "'";
if ($stav != '') {
    $sql .= " AND status = '" . $stav . "'";
}
// razeni primo z URL (!) – FIXME
$sql .= " ORDER BY " . $razeni;

$objednavky = $db->query($sql);

$pageTitle = 'Objednávky';
include LEGACY_TEMPLATES . '/partials/old_header.php';

echo '<h1>Objednávky od ' . h(datum($od)) . '</h1>';
echo '<form method="get">';
echo 'Od: <input type="text" name="od" value="' . h($od) . '" size="10"> ';
echo 'Stav: <select name="stav"><option value="">vše</option>';
foreach ($GLOBALS['ORDER_STATES'] as $k => $v) {
    echo '<option value="' . $k . '"' . ($k == $stav ? ' selected' : '') . '>' . $v . '</option>';
}
echo '</select> ';
echo '<input type="submit" value="Zobrazit"></form>';

echo '<table class="grid">';
echo '<tr><th>#</th><th>Datum</th><th>Zákazník</th><th>Stav</th><th>Položek</th><th>Celkem</th></tr>';
$i = 0;
$celkem = 0;
foreach ($objednavky as $o) {
    $i++;
    $polozky = $db->query("SELECT * FROM order_items WHERE order_id = '" . $o['id'] . "'");
    $suma = 0;
    $kusu = 0;
    foreach ($polozky as $p) {
        $suma += $p['quantity'] * $p['unit_price_amount_in_cents'];
        $kusu += $p['quantity'];
    }
    // celkem jen CZK, ostatni meny se nescitaji (2014 jsme meli jen CZK)
    if ($o['currency'] == 'CZK' && $o['status'] != 'cancelled') {
        $celkem += $suma;
    }
    echo '<tr' . ($o['status'] == 'cancelled' ? ' style="color:#999"' : '') . '>';
    echo '<td>' . $i . '</td>';
    echo '<td>' . datum($o['placed_at']) . '</td>';
    echo '<td>' . h(customer_name($o['customer_id'])) . '</td>';
    echo '<td>' . order_state_label($o['status']) . '</td>';
    echo '<td class="num">' . $kusu . '</td>';

